--Script de creación de base de datos de ventas
--=========================================================
   
   IF DB_ID ('BD_RETAILPRO_DAIANA') IS NULL CREATE DATABASE BD_RETAILPRO_DAIANA;
   GO
   USE BD_RETAILPRO_DAIANA;
   GO

-- 1. BORRADO DE TABLAS

DROP TABLE IF EXISTS Ventas;
DROP TABLE IF EXISTS Stock;
DROP TABLE IF EXISTS Vendedores;
DROP TABLE IF EXISTS Productos;
DROP TABLE IF EXISTS Clientes;
DROP TABLE IF EXISTS Sucursales;
DROP TABLE IF EXISTS Categorias;
DROP TABLE IF EXISTS Territorios;


-- 2. CREACIÓN DE TABLAS (DDL)

CREATE TABLE Territorios (
	Id_territorio	INT				IDENTITY (1,1)	NOT NULL,
	Provincia		VARCHAR (50)					NOT NULL,
	Region			VARCHAR (50)					NOT NULL,
	Zona			VARCHAR (50)					NULL,
	Pais			VARCHAR (50)					NOT NULL,
	Tiene_local		BIT								NOT NULL, -- 1 = tiene local, 0 = no tiene local
	CONSTRAINT PK_territorios PRIMARY KEY (Id_territorio)
);

CREATE TABLE Categorias (
	Id_categoria		INT				IDENTITY (1,1)	NOT NULL,
	Nombre_categoria	VARCHAR (50)					NOT NULL, 
	CONSTRAINT PK_categorias PRIMARY KEY (Id_categoria)
);

CREATE TABLE Sucursales (
	Id_sucursal		INT				IDENTITY (1,1)	NOT NULL,
	Nombre_sucursal VARCHAR (50)					NOT NULL,
	Tipo			VARCHAR (50)					NOT NULL, -- Sucursal fisica / Sucursal online
	Id_territorio	INT								NOT NULL,
	CONSTRAINT PK_sucursales PRIMARY KEY (Id_sucursal),
	CONSTRAINT FK_sucursales_territorios FOREIGN KEY (Id_territorio)
		REFERENCES Territorios (Id_territorio)
);

CREATE TABLE Clientes (
	Id_cliente		INT				IDENTITY (1,1)	NOT NULL,
	Nombre			VARCHAR (100)					NOT NULL,
	Email			VARCHAR (100)					NULL,
	Ciudad			VARCHAR (100)					NULL,
	Tipo_cliente	VARCHAR (20)					NOT NULL,
	Id_territorio	INT								NOT NULL,
	Lista_precios	VARCHAR (20)					NULL,
	Fecha_registro	DATE							NOT NULL,
	CONSTRAINT PK_clientes PRIMARY KEY (Id_cliente),
	CONSTRAINT FK_clientes_territorios FOREIGN KEY (Id_territorio)
		REFERENCES Territorios(Id_territorio),
	CONSTRAINT UQ_clientes_email UNIQUE (Email)
);

CREATE TABLE Productos (
	Id_producto		INT				IDENTITY (1,1)	NOT NULL,
	Nombre_producto	VARCHAR (100)					NOT NULL,
	Id_categoria	INT								NOT NULL,
	Subcategoria	VARCHAR (100)					NOT NULL,
	Marca			VARCHAR (50)					NOT NULL,
	Precio			DECIMAL (12,2)					NOT NULL,
	Costo			DECIMAL (12,2)					NOT NULL,
	Activo			BIT								NOT NULL DEFAULT 1, -- 1 = se vende, 0 = discontinuado
	CONSTRAINT PK_productos PRIMARY KEY (Id_producto),
	CONSTRAINT FK_productos_categorias FOREIGN KEY (Id_categoria)
		REFERENCES Categorias (Id_categoria)
);

CREATE TABLE Vendedores (
	Id_vendedor		INT				IDENTITY (1,1)	NOT NULL,
	Nombre			VARCHAR (100)					NOT NULL, 
	Id_sucursal		INT								NOT NULL,
	CONSTRAINT PK_vendedores PRIMARY KEY (Id_vendedor),
	CONSTRAINT FK_vendedores_sucursales FOREIGN KEY (Id_sucursal)
		REFERENCES Sucursales (Id_sucursal)
);

CREATE TABLE Stock (
	Id_sucursal				INT		NOT NULL,
	Id_producto				INT		NOT NULL,
	Cantidad				INT		NOT NULL DEFAULT 0,
	Fecha_actualizacion		DATE	NOT NULL,
	CONSTRAINT PK_stock PRIMARY KEY (Id_sucursal,Id_producto),
	CONSTRAINT FK_stock_sucursales FOREIGN KEY (Id_sucursal)
		REFERENCES Sucursales (Id_sucursal),
	CONSTRAINT FK_stock_productos FOREIGN KEY (Id_producto)
		REFERENCES Productos (Id_producto)
);

CREATE TABLE Ventas (
	Id_venta				INT		IDENTITY(1,1)	NOT NULL,
	Nro_pedido				INT						NOT NULL,
	Fecha_venta				DATE					NOT NULL,
	Id_cliente				INT						NOT NULL,
	Id_producto				INT						NOT NULL,
	Id_vendedor				INT						NULL, -- NULL en caso de ventas online
	Id_sucursal_venta		INT						NOT NULL,
	Id_sucursal_despacho	INT						NOT NULL,
	Cantidad				INT						NOT NULL,
	Precio_unitario			DECIMAL (12,2)			NOT NULL,
	Descuento_promo			DECIMAL (5,2)			NOT NULL DEFAULT 0,
	Cantidad_devuelta		INT						NOT NULL DEFAULT 0,
	Total_venta				DECIMAL (12,2)			NOT NULL,
	Medio_contacto			VARCHAR (30)			NULL,
	Costo_envio				DECIMAL (12,2)			NOT NULL DEFAULT 0,
	Forma_pago				VARCHAR (30)			NOT NULL, 
	Cuotas					INT						NOT NULL DEFAULT 1,
	Cuotas_sin_interes		BIT						NOT NULL DEFAULT 0,
	Costo_financiacion		DECIMAL (12,2)			NOT NULL DEFAULT 0,
	Condicion_venta			VARCHAR (20)			NOT NULL,
	Plazo_dias				INT						NOT NULL DEFAULT 0,
	Fecha_cobro				DATE					NULL, -- NULL si todavia no se cobro
	Comision_vendedor		DECIMAL (12,2)			NOT NULL DEFAULT 0,
	CONSTRAINT PK_ventas PRIMARY KEY (Id_venta),
	CONSTRAINT FK_ventas_clientes FOREIGN KEY (Id_cliente)
		REFERENCES Clientes (Id_cliente),
	CONSTRAINT FK_ventas_productos FOREIGN KEY (Id_producto)
		REFERENCES Productos (Id_producto),
	CONSTRAINT FK_ventas_vendedores FOREIGN KEY (Id_vendedor)
		REFERENCES Vendedores (Id_vendedor),
	CONSTRAINT FK_ventas_sucursal_venta FOREIGN KEY (Id_sucursal_venta)
		REFERENCES Sucursales (Id_sucursal),
	CONSTRAINT FK_ventas_sucursal_despacho FOREIGN KEY (Id_sucursal_despacho)
		REFERENCES Sucursales (Id_sucursal)
);


